p='src/types/checker/functions/resolution/signature.rs'
s=open(p).read()
old = """/// Returns whether an array-ish type's ELEMENT representation CHANGED across the body.
///
/// Any change matters, not only a widening to `Mixed`: an empty `array<never>` that the body
/// appends ints to becomes `array<int>`, and the caller keeps its own pointer to the empty one
/// unless it is told. `never` on the way OUT is not a change — a body that only reads leaves the
/// element type where the checker's join put it.
///
/// The container kind has to match: an `Array` that became an `AssocArray` is a different change,
/// already carried by the ordinary storage machinery.
pub(in crate::types) fn array_element_representation_changes(entry: &PhpType, exit: &PhpType) -> bool {
    match (entry.codegen_repr(), exit.codegen_repr()) {
        (PhpType::Array(entry_elem), PhpType::Array(exit_elem)) => {
            exit_elem.codegen_repr() != PhpType::Never
                && entry_elem.codegen_repr() != exit_elem.codegen_repr()
        }
        (
            PhpType::AssocArray {
                value: entry_value, ..
            },
            PhpType::AssocArray {
                value: exit_value, ..
            },
        ) => {
            exit_value.codegen_repr() != PhpType::Never
                && entry_value.codegen_repr() != exit_value.codegen_repr()
        }
        _ => false,
    }
}"""
new = """/// Returns whether an array-ish type's ELEMENT representation WIDENED from `entry` to `exit`.
///
/// Two widenings matter, and only those two. An element representation that became `Mixed` means
/// boxed slots where there were raw ones. An empty `array<never>` that gained an element type
/// means slots where there were none. The direction is load-bearing: a callee compiled for
/// `array<int>` must never re-type a caller holding `array<mixed>`, because it cannot unbox
/// storage it does not own.
///
/// The container kind has to match: an `Array` that became an `AssocArray` is a different change,
/// already carried by the ordinary storage machinery.
pub(in crate::types) fn array_element_representation_widens(entry: &PhpType, exit: &PhpType) -> bool {
    match (entry.codegen_repr(), exit.codegen_repr()) {
        (PhpType::Array(entry_elem), PhpType::Array(exit_elem)) => {
            element_representation_widens(&entry_elem, &exit_elem)
        }
        (
            PhpType::AssocArray {
                value: entry_value, ..
            },
            PhpType::AssocArray {
                value: exit_value, ..
            },
        ) => element_representation_widens(&entry_value, &exit_value),
        _ => false,
    }
}

/// Returns whether one array element representation is wider than another.
fn element_representation_widens(entry: &PhpType, exit: &PhpType) -> bool {
    let entry = entry.codegen_repr();
    let exit = exit.codegen_repr();
    if entry == exit {
        return false;
    }
    entry == PhpType::Never || exit == PhpType::Mixed
}"""
